// Soru verisi. act: [model, x(merkez), y(taban), boy, animasyon, aynala?, gecikme?]
// in: giriş hikâyesi satırları · s: adım adım çözüm · w: neden işe yarıyor · h: tarihçe · n: ilginç not
const L1=["l1","Kolay"],L2=["l2","Orta"],L3=["l3","Zor"],L4=["l4","Çok Zor"];

const PUZ=[
 {t:"Kurt, Kuzu ve Ot",lv:L1,bg:"river",
  act:[["wolf",28,104,44,"bob"],["sheep",62,104,38,"bob",0,.3],["cabbage",84,104,22,"pulse"],["boat",130,138,64,"row",0,0],["farmer",130,118,46,"row",0,0]],
  in:["Bir çiftçi pazardan bir kurt, bir kuzu ve bir lahana almış.","Önünde geniş bir nehir ve sadece ikisini taşıyabilen minicik bir sandal var.","Dikkat! Çiftçi yokken kurt kuzuyu, kuzu da lahanayı afiyetle yer..."],
  q:"Çiftçinin sandalına kendisi + yalnızca 1 şey sığar. Çiftçi yokken kurt kuzuyu, kuzu da otu yer. Hepsini karşıya taşı!",
  g:(el,api)=>river(el,api,{items:[{id:"f",m:"farmer",name:"Çiftçi"},{id:"w",m:"wolf",name:"Kurt"},{id:"g",m:"sheep",name:"Kuzu"},{id:"c",m:"cabbage",name:"Ot"}],cap:2,rower:["f"],rowMsg:"Sandalı sadece çiftçi kullanabilir!",capMsg:"Sandala çiftçi + 1 şey sığar!",hint:"Çiftçiye ve götüreceğin şeye tıkla → sandala binerler. Sonra ⛵ Karşıya geç.",
   check:s=>{const a=s.f==="L"?"R":"L";if(s.w===a&&s.g===a)return"😱 Kurt kuzuyu yedi!";if(s.g===a&&s.c===a)return"😱 Kuzu otu yedi!"},goal:s=>Object.values(s).every(v=>v==="R"),end:(st,api)=>st.n===7?api.win("Mükemmel! 7 geçişle en kısa çözüm 🏆"):api.win(`Başardın! (${st.n} geçiş — 7'de yapılabilir)`)}),
  a:"7 geçiş",
  s:["Kuzuyu karşıya götür (kurt ile ot yan yana kalabilir).","Boş dön.","Kurdu karşıya götür.","Kuzuyu GERİ getir — işin sırrı bu hamle!","Otu karşıya götür (kurt ile ot yine güvenle yan yana).","Boş dön.","Kuzuyu tekrar götür. Herkes karşıda!"],
  w:"Tehlikeli ikililer kuzu üzerinden geçiyor: kurt–kuzu ve kuzu–ot. Kuzu 'problemli' olan tek eleman, bu yüzden sandalda en çok o yolculuk yapar. Bulmacanın kilidi, geri dönüşte boş gelmek zorunda olmadığını fark etmek: bir şeyi geri götürmek de ilerlemenin parçası olabilir. Bilgisayar bilimciler bu tür sorunları 'durum uzayı araması' ile çözer: her olası diziliş bir düğüm, her geçiş bir kenardır.",
  h:"Bilinen en eski kaynağı, Şarlman'ın sarayındaki bilgin <b>Yorklu Alcuin</b>'e (735–804) atfedilen <i>Propositiones ad Acuendos Juvenes</i> (Gençlerin Zihnini Keskinleştirmek İçin Problemler, ~MS 800) adlı Latince kitaptır. Orada kurt, keçi ve bir demet lahana olarak geçer. Aynı bulmaca Afrika'da (çita–keçi–yam), Etiyopya'da ve Rus halk masallarında da farklı hayvanlarla anlatılır.",
  n:"Bu bulmacanın iki farklı 7 adımlı çözümü vardır: 3. adımda kurt yerine otu götürmek de işe yarar."},

 {t:"Asker ve İki Çocuk",lv:L1,bg:"river",
  act:[["soldier",30,104,54,"bob"],["boat",160,138,64,"row",0,0],["boy",150,118,34,"row",0,0],["girl",172,118,34,"row",0,0]],
  in:["Bir askerin acil bir mesajı karşı kıyıya ulaştırması lazım.","Köprü yıkılmış; kıyıda sadece iki çocuğun küçük sandalı var.","Sandal bir yetişkini ya da iki çocuğu taşıyabiliyor. Üstelik çocuklar sandallarını geri istiyor!"],
  q:"Bir asker nehri geçmeli. Sandal ya iki çocuğu ya da tek bir yetişkini taşıyabilir. Asker karşıya geçtikten sonra sandal yine çocukların başladığı kıyıda olmalı.",
  g:(el,api)=>river(el,api,{items:[{id:"s",m:"soldier",name:"Asker",w:2},{id:"k1",m:"boy",name:"Ali"},{id:"k2",m:"girl",name:"Ayşe"}],cap:2,capMsg:"Sandal 2 çocuk YA DA 1 yetişkin taşır!",hint:"Asker karşıya geçsin; sandal ve çocuklar başlangıç kıyısında kalsın.",
   goal:(s,b)=>s.s==="R"&&s.k1==="L"&&s.k2==="L"&&b==="L",end:(st,api)=>st.n<=4?api.win("Görev tamam! 4 geçiş: en kısa yol 🎖️"):api.win(`Başardın! (${st.n} geçiş — 4'te yapılabilir)`)}),
  a:"4 geçiş",
  s:["İki çocuk birlikte karşıya geçer.","Bir çocuk sandalla geri döner.","Asker tek başına karşıya geçer.","Karşıda bekleyen çocuk sandalı geri getirir. Artık iki çocuk ve sandal başlangıçta, asker karşıda."],
  w:"Askeri taşıyan her yolculuktan sonra sandalı birinin geri getirmesi gerekir. Çocukları önceden karşıya 'yerleştirmek' bu geri dönüşü mümkün kılar. Bu 4 adımlık döngü sonunda her şey başa döner — yalnızca asker yer değiştirmiştir. Matematikte buna 'değişmez (invariant)' durum denir: döngü ne kadar tekrarlanırsa tekrarlansın çocukların konumu korunur.",
  h:"Bu bulmaca 19. yüzyıl Avrupa ve Rus bulmaca kitaplarında yaygındır. Özellikle <b>Boris Kordemsky</b>'nin (1907–1999) 1956'da yayımlanan ve milyonlarca satan <i>Moskova Bulmacaları</i> gibi klasik derlemelerde bu tür 'kapasiteli sandal' problemleri bolca bulunur.",
  n:"Bütün bir bölüğün (örneğin 100 askerin) geçmesi için döngü 100 kez tekrarlanır: 400 geçiş!"},

 {t:"Köprü ve Fener",lv:L2,bg:"bridge",
  act:[["runner",40,98,44,"walk",0,0],["lantern",62,80,22,"walk",0,0],["man",80,98,44,"walk",0,0],["lady",240,98,44,"bob",1],["oldman",280,98,44,"bob",1]],
  in:["Gece yarısı... Dört arkadaş eski, çürük bir asma köprünün başında.","Köprü aynı anda en fazla iki kişiyi taşıyor ve ellerinde tek bir fener var.","Pil 17 dakika sonra bitecek. Fenersiz köprüye adım atmak ölümcül!"],
  q:"Dört kişi çürük bir köprüden geçecek. Köprü aynı anda en çok 2 kişi taşıyor, tek fener var. Süreler: 1, 2, 5, 10 dk. İkili yavaş olanın hızında yürür. 17 dakikada herkesi geçir!",
  g:(el,api)=>river(el,api,{night:1,time:1,items:[{id:"a",m:"runner",name:"1 dk",t:1},{id:"b",m:"man",name:"2 dk",t:2},{id:"c",m:"lady",name:"5 dk",t:5},{id:"d",m:"oldman",name:"10 dk",t:10}],cap:2,capMsg:"Köprü en çok 2 kişi taşır!",hint:"Feneri taşıyacak kişileri seç ve köprüden geçir. Hedef: 17 dk.",
   goal:s=>Object.values(s).every(v=>v==="R"),end:(st,api)=>st.t<=17?api.win(`Herkes geçti: ${st.t} dakika! Mükemmel 🔦`):api.fail(`Herkes geçti ama ${st.t} dakika sürdü. 17'de yapılabilir!`)}),
  a:"17 dakika",
  s:["1 ve 2 dakikalık kişiler geçer → 2 dk","1 dakikalık feneri geri getirir → 1 dk (toplam 3)","5 ve 10 dakikalık kişiler BİRLİKTE geçer → 10 dk (toplam 13)","2 dakikalık feneri geri getirir → 2 dk (toplam 15)","1 ve 2 tekrar geçer → 2 dk (toplam 17)"],
  w:"Akla ilk gelen strateji 'en hızlı kişi herkese eşlik etsin'dir: 10+1+5+1+2 = 19 dk. Ama bu yöntemde 5 ve 10 dakikalıklar ayrı ayrı geçtiği için iki yavaş süre birden ödenir. Doğru çözümde en yavaş iki kişi birlikte yürüyerek 5 dakikalık süreyi 10'un 'gölgesinde' bedavaya getirir. Bedeli: fenerin iki kez hızlılarca geri taşınması. Genel kural: 2b ≤ a + c ise (a,b en hızlılar, c ikinci en yavaş) bu strateji daha iyidir: 2·2 = 4 ≤ 1+5 = 6.",
  h:"İlk kez <b>Saul X. Levmore</b> ve <b>Elizabeth Early Cook</b>'un 1981 tarihli <i>Super Strategies for Puzzles and Games</i> kitabında yayımlandı. 1990'larda Microsoft'un iş görüşmelerinde sorulan efsanevi sorulardan biri olarak ün kazandı; bu yüzden 'U2 bulmacası' (grup üyeleri konsere yetişmeye çalışır) diye de anılır.",
  n:"n kişilik genel durum için en iyi çözümü bulan algoritma 2000'lerin başında matematiksel olarak kanıtlandı (Rote, 2002)."},

 {t:"İki Kova ile 4 Litre",lv:L2,bg:"lab",
  act:[["bucket",110,128,66,"tilt"],["bucket",210,128,48,"bob",0,.4],["drop",160,70,26,"float"]],
  in:["Çölün ortasındaki bir çeşmenin başındasın.","Bir büyücü tam 4 litre su istiyor: ne bir damla eksik, ne bir damla fazla!","Ama elinde sadece 5 ve 3 litrelik, üzerinde çizgi olmayan iki kova var..."],
  q:"Elinde 5 ve 3 litrelik iki kova ile bir çeşme var. Tam 4 litre su ölç! (En az 6 işlemde yapılabilir.)",
  g:(el,api)=>jugs(el,api,[5,3],4,6),
  a:"6 işlem",
  s:["5 litrelik kovayı doldur → (5, 0)","5'likten 3'lüğü doldur → (2, 3)","3'lüğü boşalt → (2, 0)","5'likteki 2 litreyi 3'lüğe aktar → (0, 2)","5'liği yeniden doldur → (5, 2)","5'likten 3'lüğü tamamla; sadece 1 litre gider → (4, 3). 5'likte tam 4 litre!"],
  w:"Kovaların üzerinde çizgi yok; tek 'kesin' ölçüler 'tamamen dolu' ve 'tamamen boş'. Her aktarma bu iki sınırdan birine dayanır. Matematiksel olarak ölçebildiğin miktarlar 5x + 3y biçimindeki sayılardır (x, y tam sayı). EBOB(5, 3) = 1 olduğu için 0–5 arası her litre ölçülebilir; örneğin 4 = 5·2 − 3·2. Bu, sayılar kuramındaki <b>Bézout özdeşliği</b>dir.",
  h:"Su ölçme bulmacaları İtalyan matematikçi <b>Niccolò Tartaglia</b>'ya (1499–1557) kadar uzanır: 8 litrelik dolu bir testi 5 ve 3 litrelik kaplarla iki eşit parçaya bölme problemi. 1612'de Fransız <b>Claude-Gaspard Bachet de Méziriac</b> bunu ünlü bulmaca kitabına aldı. 1995 yapımı <i>Zor Ölüm 3</i> (Die Hard with a Vengeance) filminde Bruce Willis ve Samuel L. Jackson bir bombayı durdurmak için tam olarak bu bulmacayı çözer!",
  n:"Öbür yol (önce 3'lüğü doldurmak) 8 işlem sürer. Kısa yol her zaman 'büyük kovadan başla' değildir; hedefe göre değişir."},

 {t:"Ağır Bilye",lv:L2,bg:"scale",
  act:[["balance",160,134,96,"tilt"],["marble",50,134,24,"bob"],["marble",76,134,24,"bob",0,.2],["marble",244,134,24,"bob",0,.4],["marble",270,134,24,"bob",0,.6]],
  in:["Kraliyet hazinesindeki 8 altın bilyeden biri sahte!","Sahtekâr kuyumcu içine kurşun koymuş: o bilye biraz daha ağır.","Terazi bozulmadan önce sadece 2 kez kullanılabilir..."],
  q:"Görünüşü aynı 8 bilyeden biri biraz daha ağır. Sadece 2 tartımla ağır bilyeyi bul!",
  g:(el,api)=>scale(el,api,8,"heavy",2),
  a:"2 tartım",
  s:["Bilyeleri 3 – 3 – 2 olarak üç gruba ayır.","1. tartım: 3'lü grupları karşılaştır. Eşitse ağır bilye kenardaki 2'li gruptadır; değilse aşağı inen kefedeki 3'lüdedir.","2. tartım (2'li gruptaysa): ikisini karşılaştır, ağır olan aşağı iner.","2. tartım (3'lü gruptaysa): içinden ikisini karşılaştır; eşitse dışarıdaki üçüncü bilye ağırdır."],
  w:"Kilit fikir: terazinin <b>üç</b> sonucu vardır — sol, sağ ve denge. Çoğu kişi bilyeleri ikiye böler ve dengeyi boşa harcar (o zaman 3 tartım gerekir). Her tartımda adayları üçe bölersen, 2 tartımla 3 × 3 = 9 adaya kadar ayırt edebilirsin. 8 ≤ 9 olduğu için yeter. Bu bir <b>bilgi kuramı</b> argümanıdır: her tartım log₂3 ≈ 1,58 bit bilgi verir.",
  h:"'Sahte para' problemleri 20. yüzyılın başından beri bulmaca dergilerinde yer alır. Bu tür problemler 1940'larda matematik dergilerinde ciddi bir araştırma konusu haline geldi ve 'arama kuramı' (search theory) adlı dalın gelişmesine katkıda bulundu.",
  n:"Aynı yöntemle 3 tartımda 27, 4 tartımda 81 bilyeden ağır olanı bulabilirsin (3ⁿ)."},

 {t:"Yanan İki İp",lv:L3,bg:"lab",
  act:[["rope",100,128,62,"bob"],["rope",220,128,62,"bob",1,.3],["flame",72,96,28,"pulse"],["flame",248,96,28,"pulse",0,.4],["stopwatch",160,70,40,"tilt"]],
  in:["Bir zindanda saatsiz kalmışsın; muhafız tam 45 dakika sonra değişecek.","Elinde bir çakmak ve iki eski ip var. Her ip tam 1 saatte yanıyor...","...ama düzensiz! Bir yarısı 5 dakikada, öbür yarısı 55 dakikada yanabilir."],
  q:"İki ipin her biri tam 1 saatte ama düzensiz yanıyor. Bir çakmakla tam 45 dakikayı ölç ve zili çal!",
  g:ropes,
  a:"İki uçtan yakma hilesi",
  s:["Başlangıçta: A ipini İKİ ucundan, B ipini TEK ucundan yak.","A ipi tam 30 dakikada biter (iki alev ip boyunca bir yerde buluşur).","O anda B ipinde, tek uçtan yansa 30 dakika sürecek kadar ip kalmıştır. Hemen öbür ucunu da yak.","B'nin kalan kısmı iki uçtan yandığı için 15 dakikada biter.","30 + 15 = 45 dakika: zili çal!"],
  w:"İp düzensiz yandığı için 'uzunluk' zamanı göstermez; ortadan kesmek işe yaramaz. Ama <b>iki uçtan</b> yakılan ip, nasıl yanarsa yansın, toplam sürenin tam yarısında biter: iki alev birlikte 60 dakikalık 'yanma işini' paylaşır. Bu, fiziksel ölçümü değil, toplam süreyi kullanan zarif bir fikirdir.",
  h:"Bu bulmaca 20. yüzyılın sonlarında popülerleşti ve Google, Microsoft gibi şirketlerin mülakatlarında sıkça soruldu. Mantık bulmacası dünyasında 'sigorta fitili' (fuse) problemleri olarak bilinen bir ailenin üyesidir.",
  n:"İki iple 15, 30, 45 ve 60 dakika ölçülebilir; üç iple ölçülebilen süreler çok daha fazladır (7,5 dakika gibi)."},

 {t:"Misyonerler ve Yamyamlar",lv:L3,bg:"river",
  act:[["monk",20,104,36,"bob"],["monk",44,104,36,"bob",0,.2],["monk",68,104,36,"bob",0,.4],["ogre",252,104,38,"shake",1],["ogre",276,104,38,"shake",1,.2],["ogre",300,104,38,"shake",1,.4],["boat",160,138,58,"bob"]],
  in:["Üç gezgin keşiş ve üç aç dev aynı nehrin kıyısında buluştu.","İki kişilik tek bir sandal var ve herkesin karşıya geçmesi gerek.","Ama bir kıyıda devler keşişlerden fazla olursa... keşişler akşam yemeği olur!"],
  q:"3 keşiş ve 3 dev karşıya geçecek. Sandal en çok 2 kişi alır. Hiçbir kıyıda devler keşişlerden fazla olamaz (orada keşiş varsa).",
  g:(el,api)=>river(el,api,{size:46,items:[1,2,3].map(i=>({id:"m"+i,m:"monk",name:"Keşiş"})).concat([1,2,3].map(i=>({id:"c"+i,m:"ogre",name:"Dev"}))),cap:2,capMsg:"Sandal en çok 2 kişi alır!",hint:"Kıyılarda dengeyi koru!",
   check:s=>{for(const k of["L","R"]){const m=Object.keys(s).filter(i=>i[0]==="m"&&s[i]===k).length,c=Object.keys(s).filter(i=>i[0]==="c"&&s[i]===k).length;if(m>0&&c>m)return`😱 ${k==="L"?"Sol":"Sağ"} kıyıda devler sayıca üstün!`}},
   goal:s=>Object.values(s).every(v=>v==="R"),end:(st,api)=>st.n===11?api.win("Herkes güvende! 11 geçiş: en kısa çözüm 🏆"):api.win(`Başardın! (${st.n} geçiş — 11'de yapılabilir)`)}),
  a:"11 geçiş",
  s:["2 dev geçer.","1 dev döner.","2 dev geçer (karşıda 3 dev, başta 3 keşiş).","1 dev döner.","2 keşiş geçer (karşıda 2K + 1D).","1 keşiş + 1 dev döner — kritik hamle!","2 keşiş geçer (karşıda 3 keşiş + 1 dev, başta sadece 2 dev).","1 dev döner.","2 dev geçer.","1 dev döner.","Son 2 dev geçer. Herkes karşıda!"],
  w:"Durumu (soldaki keşiş, soldaki dev, sandalın yeri) üçlüsüyle gösterirsek sadece 16 güvenli durum vardır. Bunları bir harita gibi çizip başlangıçtan hedefe en kısa yolu aramak çözümü verir. 6. adım sezgiye ters gelir: ilerlemek için iki kişiyi geri göndermek gerekir. Yapay zekâ derslerinde 'genişlik öncelikli arama' (BFS) anlatılırken en çok kullanılan örnektir.",
  h:"Kökeni yine Alcuin'in ~MS 800 tarihli kitabındaki '<b>kıskanç kocalar</b>' problemine dayanır: üç çift nehri geçer ve hiçbir kadın, kocası yanında değilken başka bir erkekle kalamaz. 19. yüzyılda 'misyonerler ve yamyamlar' biçimini aldı. 1968'de <b>Saul Amarel</b> problemi 'problem temsili' üzerine çığır açan yapay zekâ makalesinde kullandı.",
  n:"4 keşiş ve 4 devle (2 kişilik sandalla) problem çözümsüzdür! 3 kişilik sandal gerekir."},

 {t:"Doğrucu ve Yalancı Bekçi",lv:L3,bg:"doors",
  act:[["guard",40,134,66,"bob"],["door",122,134,74,"pulse"],["door",198,134,74,"pulse",0,.5],["guard",280,134,66,"bob",1,.3],["bubble",160,56,40,"float"]],
  in:["Bir labirentin sonunda iki kapı var: biri özgürlüğe, biri ejderhanın inine.","Her kapıda bir bekçi duruyor. Biri asla yalan söylemez, öbürü asla doğruyu söylemez.","Kim hangisi bilmiyorsun ve sadece bir bekçiye tek bir soru sorabilirsin..."],
  q:"Bir kapı özgürlüğe, biri ejderhaya. Bekçilerden biri hep doğru, öbürü hep yalan söyler. Tek bekçiye tek soru sorabilirsin. Garanti kurtul!",
  g:guards,
  a:"\"Öbür bekçi hangisini gösterirdi?\" diye sor, tersini seç",
  s:["Herhangi bir bekçiye sor: 'Öbür bekçiye özgürlük kapısını sorsam hangisini gösterirdi?'","Doğrucuya sorduysan: yalancının yanlış kapıyı göstereceğini dürüstçe söyler → yanlış kapıyı gösterir.","Yalancıya sorduysan: doğrucu doğru kapıyı gösterirdi; yalancı bunu çarpıtır → yine yanlış kapıyı gösterir.","Her iki durumda da gösterilen kapı yanlış. Öbür kapıdan geç!"],
  w:"Kimin yalancı olduğunu bulmak gerekmez; soruyu öyle kurarız ki cevap, kim cevap verirse versin aynı olur. Soru iki bekçiyi zincirlediği için cevap her zaman tam olarak bir 'doğru' ve bir 'yalan' süzgecinden geçer. Mantıkta bu, iki olumsuzlamadan biri tek sayıda kalınca sonucun tersine dönmesidir: (+)·(−) = (−). Alternatif soru: 'Sana öbür bekçinin ne diyeceğini sorsam ne derdin?' gibi öz-göndermeli sorular da çalışır.",
  h:"Doğrucular ve yalancılar bulmacalarının büyük ustası, Amerikalı matematikçi ve mantıkçı <b>Raymond Smullyan</b>'dır (1919–2017). 1978 tarihli kitabı <i>Bu Kitabın Adı Ne?</i> (What Is the Name of This Book?) bu bulmacaları dünyaya yaydı. Bu iki kapılı sürüm ise 1986 yapımı <i>Labirent</i> (Labyrinth) filminde, David Bowie'nin rol aldığı sahnelerle ünlendi.",
  n:"Smullyan bu bulmacaları sonunda Gödel'in eksiklik teoremini anlatmak için kullandı!"},

 {t:"12 Bilye, Biri Farklı",lv:L4,bg:"scale",
  act:[["balance",160,134,96,"tilt"],["marble",36,134,20,"bob"],["marble",58,134,20,"bob",0,.2],["marble",80,134,20,"bob",0,.4],["marble",240,134,20,"shake"],["marble",262,134,20,"bob",0,.3],["marble",284,134,20,"bob",0,.5]],
  in:["Bu kez işler zor: 12 bilyeden biri sahte.","Ama sahtekâr kuyumcu sinsi; sahte bilye ağır mı hafif mi, bilmiyorsun!","Terazi sadece 3 kez kullanılabilir. Hem sahteyi bul, hem ağır mı hafif mi söyle."],
  q:"12 bilyeden biri farklı ağırlıkta ama AĞIR mı HAFİF mi bilmiyorsun. 3 tartımla hem bilyeyi hem ağır/hafif olduğunu bul!",
  g:(el,api)=>scale(el,api,12,"either",3),
  a:"3 tartım",
  s:["Bilyeleri dörderli üç gruba ayır: A = 1–4, B = 5–8, C = 9–12. 1. tartım: A ile B.","DENGEDEYSE: farklı bilye C'de. 2. tartım: {9, 10, 11} ile sağlam olduğu bilinen {1, 2, 3}.","  • Yine dengedeyse 12 farklıdır → 3. tartım: 12'yi 1 ile karşılaştır, ağır mı hafif mi anlaşılır.","  • Dengede değilse yön belli oldu (ör. ağır). 3. tartım: 9 ile 10; eşitse 11, değilse ağır olan.","A AĞIR GELDİYSE: (1–4 ağır adayı, 5–8 hafif adayı). 2. tartım: {1, 2, 5} ile {3, 6, 9}.","  • Dengedeyse: 4 ağır ya da 7/8 hafif. 3. tartım: 7 ile 8 → hafif olan çıkar; eşitse 4 ağırdır.","  • Sol ağırsa: 1 ya da 2 ağır, veya 6 hafif. 3. tartım: 1 ile 2 → ağır olan; eşitse 6 hafif.","  • Sağ ağırsa: 3 ağır ya da 5 hafif. 3. tartım: 3 ile sağlam 9 → eşitse 5 hafif, değilse 3 ağır."],
  w:"Olası durum sayısı 12 bilye × 2 (ağır/hafif) = 24. Üç tartımın en fazla 3³ = 27 farklı sonucu var, yani teorik olarak mümkün ama çok az pay kalıyor. Sırrı, 2. tartımda bilyeleri <b>kefeler arasında yer değiştirmek</b> (5 sola, 3 sağa geçiyor): terazinin eğilme yönünün değişip değişmediği, hangi bilyenin suçlu olduğunu ele verir. Kanıtlanmış sınır: n tartımla en çok (3ⁿ − 3)/2 bilye çözülebilir → 3 tartım için 12.",
  h:"1945'te Amerikan Matematik Dergisi'nde (<i>American Mathematical Monthly</i>) E. D. Schell tarafından sorulduğu kabul edilir. İkinci Dünya Savaşı yıllarında bilim insanları arasında öyle bir salgın gibi yayıldı ki, bir İngiliz bilim insanının bulmacanın 'Almanya üzerine atılıp düşman bilim insanlarının vaktini çalması' gerektiğini söylediği anlatılır. Ünlü fizikçi <b>Freeman Dyson</b> 1946'da genel çözümü veren bir makale yayımladı.",
  n:"13 bilyede de 3 tartımla farklı olanı bulabilirsin ama bu kez ağır mı hafif mi olduğunu her zaman söyleyemezsin."},

 {t:"1000 Şişe ve Fareler",lv:L4,bg:"lab",
  act:[["bottle",36,128,40,"bob"],["bottle",66,128,40,"bob",0,.2],["poison",96,128,40,"pulse"],["bottle",126,128,40,"bob",0,.4],["mouse",210,128,40,"walk"],["mouse",250,128,40,"bob",1,.3],["mouse",290,128,40,"walk",1,.6]],
  in:["Bir kralın şölenine 1000 şişe şarap geldi; ama casuslar birini zehirlemiş!","Zehir sinsi: içen 24 saat sonra bayılıyor. Şölen ise tam 24 saat sonra.","Laboratuvarda gönüllü fareler var. Kral, olabildiğince az fareyi riske atmak istiyor."],
  q:"1000 şişeden biri zehirli; zehir 24 saatte etki ediyor ve tek test turun var. En az kaç fare gerekir? Önce küçük modelde dene: 8 şişe, 3 fare!",
  g:bottles,
  a:"10 fare",
  s:["Şişeleri 0'dan 999'a kadar numarala ve her numarayı ikili (binary) sayıyla yaz. 10 basamak yeter: 2¹⁰ = 1024 ≥ 1000.","Her fare bir basamağı (bit'i) temsil etsin: 1. fare 1. basamak, 2. fare 2. basamak...","Şişe numarasının k. basamağı 1 ise o şişeden k. fareye bir damla ver. (Örn. 5 = 0000000101 → 1. ve 3. fareler içer.)","24 saat sonra bayılan fareleri '1', ayakta kalanları '0' olarak yaz.","Ortaya çıkan 10 basamaklı ikili sayı, zehirli şişenin numarasıdır!"],
  w:"Her fare tek bir soru cevaplar: 'zehirli şişe benim grubumda mı?' — evet ya da hayır, yani 1 bit. 10 farenin cevap kombinasyonu 2¹⁰ = 1024 farklı olasılığı ayırt eder. Ayrıca hiçbir fare bayılmazsa zehirli şişe 0 numaralıdır; bu durum da bilgi taşır! Bu, verileri 'kodlama' ile sıkıştırmanın en saf örneğidir.",
  h:"Bulmaca modern bir mülakat klasiğidir, ama arkasındaki fikir <b>Claude Shannon</b>'ın (1916–2001) 1948'de yayımladığı ve 'bilgi çağını' başlatan <i>İletişimin Matematiksel Kuramı</i> makalesine dayanır: bilgi bit ile ölçülür. Benzer bir yöntem İkinci Dünya Savaşı sırasında ABD ordusunda kan örneklerini gruplayarak toplu test yapmak için (Robert Dorfman, 1943) önerildi. COVID-19 salgınında da 'havuz testi' adıyla kullanıldı.",
  n:"İki tur test yapma şansın olsaydı, 'üçlük sayı sistemi' fikriyle daha az fare yeterdi."},

 {t:"Üç Anahtar, Bir Ampul",lv:L2,nw:1,bg:"room",
  act:[["switchm",40,128,44,"bob"],["switchm",80,128,44,"bob",0,.2],["switchm",120,128,44,"bob",0,.4],["door",200,130,70,"none"],["bulb",270,90,60,"blink"]],
  in:["Eski bir köşkün bodrum koridorundasın. Duvarda üç elektrik anahtarı var.","Bunlardan sadece biri, kapısı kapalı odadaki ampulü yakıyor.","Kapı sadece bir kez açılıyor ve içeri girince bir daha anahtarlara dönemiyorsun..."],
  q:"Koridorda 3 anahtar var, biri kapalı odadaki ampulü yakıyor. Anahtarlarla istediğin kadar oynayabilirsin ama odaya sadece BİR KEZ girebilirsin. Hangi anahtar?",
  g:lights,
  a:"Isıyı kullan",
  s:["1. anahtarı aç ve 10 dakika kadar bekle.","1. anahtarı kapat, 2. anahtarı aç ve hemen odaya gir.","Ampul yanıyorsa → 2. anahtar.","Sönük ama dokununca sıcaksa → 1. anahtar (bir süre yanıp sönmüş).","Sönük ve soğuksa → 3. anahtar."],
  w:"Tek bir bakışla ampul 'yanık' ya da 'sönük': yalnızca 2 durum. Üç anahtarı ayırt etmek için 3 durum gerekir. Sır, ampulün sadece ışık değil ısı da üretmesidir: zamanı bir bilgi kanalı olarak kullanıp sıcaklıkta bir 'iz' bırakırsın. Bu bulmaca, kutunun dışında düşünmenin — sorunun açıkça söylemediği fiziksel özellikleri kullanmanın — klasik örneğidir.",
  h:"20. yüzyılın ortalarından beri bilinen bir 'yanal düşünme' (lateral thinking) bulmacasıdır. Bu terimi 1967'de Maltalı düşünür <b>Edward de Bono</b> ortaya attı. Bulmaca, akkor flamanlı ampullerin dönemine aittir: günümüzün LED ampulleri çok az ısındığı için çözüm modern evlerde pek işe yaramayabilir!",
  n:"Aynı fikirle 4 anahtar da çözülebilir: biri uzun süre açık, biri kısa süre açık, biri açık, biri kapalı → 'çok sıcak, ılık, yanık, soğuk'."},

 {t:"Atlayan Kurbağalar",lv:L2,nw:1,bg:"pond",
  act:[["frog",40,128,38,"hop"],["frog",80,128,38,"hop",0,.3],["frog",120,128,38,"hop",0,.6],["frog",200,128,38,"hop",1,.15],["frog",240,128,38,"hop",1,.45],["frog",280,128,38,"hop",1,.75]],
  in:["Göldeki dar bir nilüfer yolunda iki kurbağa ailesi karşı karşıya geldi.","Yeşiller sağa, maviler sola gitmek istiyor; aralarında sadece bir boş yaprak var.","Kurbağalar inatçı: asla geri gitmezler!"],
  q:"Üç yeşil kurbağa sağa, üç mavi kurbağa sola gitmek istiyor. Kurbağalar sadece ileri gider: boş yaprağa adım atar ya da bir kurbağanın üstünden atlar. Yer değiştirt!",
  g:frogs,
  a:"15 hamle",
  s:["Altın kural: Aynı renkten iki kurbağayı boşluğun önünde yan yana sıkıştırma; renkleri hep dönüşümlü (yeşil-mavi-yeşil...) diz.","Hamleler dalga dalga ilerler: 1 yeşil, 2 mavi, 3 yeşil, 3 mavi, 3 yeşil, 2 mavi, 1 yeşil = 15 hamle.","Örnek başlangıç: Yeşil3 adım → Mavi1 atlar → Mavi2 adım → Yeşil3 atlar → Yeşil2 atlar → Yeşil1 adım...","Sonuç: 9 atlama + 6 kısa adım = 15 hamle."],
  w:"Her yeşil kurbağa her mavi kurbağayla tam bir kez karşılaşmalı ve aralarında bir atlama olmalı: 3 × 3 = 9 atlama. Ayrıca her kurbağa toplam 4 yer ilerlemeli; 6 kurbağa × 4 = 24 kare. Atlamalar 2 kare, adımlar 1 kare götürür: 9×2 + 6×1 = 24. Bu yüzden 15'ten az hamle imkânsızdır. Genel formül: n çift için n² + 2n hamle.",
  h:"'Kurbağalar ve kara kurbağalar' (frogs and toads) bulmacası 19. yüzyılda popülerdi. Fransız matematikçi <b>Édouard Lucas</b> (1842–1891), 1883'te yayımlanan dört ciltlik <i>Récréations Mathématiques</i> eserinde bu tür yer değiştirme oyunlarını inceledi.",
  n:"n kurbağa çifti için gereken hamle sayıları: 3, 8, 15, 24, 35... (bunlar tam karelerden bir eksiktir: (n+1)² − 1)."},

 {t:"Kum Saatleriyle Yumurta",lv:L3,nw:1,bg:"kitchen",
  act:[["hourglass",70,128,64,"tilt"],["pot",160,132,70,"bob"],["egg",160,70,28,"float"],["hourglass",250,128,64,"tilt",0,.6]],
  in:["Ünlü bir şef, yarışmada kusursuz bir rafadan yumurta istiyor: tam 15 dakika!","Mutfakta saat yok; sadece 7 ve 11 dakikalık iki eski kum saati var.","Jüri bekliyor... Kum saatlerini nasıl kullanacaksın?"],
  q:"Elinde 7 ve 11 dakikalık iki kum saati var. Bir yumurtayı TAM 15 dakika haşlaman lazım. Nasıl?",
  g:(el,api)=>hourglass(el,api,[7,11],15),
  a:"İki kum saatinin farkını kullan (11 − 7 = 4)",
  s:["Yumurtayı suya at ve iki kum saatini aynı anda çevir. (0. dakika)","7'lik bitti → hemen ters çevir. (7. dakika)","11'lik bitti → bu anda 7'lik 4 dakikadır akıyor. 7'liği tekrar çevir: üstte tam 4 dakikalık kum var. (11. dakika)","7'lik biter → 11 + 4 = 15. dakika. Yumurtayı çıkar!","Alternatif: İkisini çevir; 7'lik bitince yumurtayı at. 11'lik 4 dk sonra biter; hemen çevir, 11 dk daha: 4 + 11 = 15."],
  w:"Kum saatleri birer 'zaman kovası'dır; su ölçme bulmacasıyla aynı mantık! Ölçebileceğin süreler 7x + 11y biçimindedir. 11 − 7 = 4 dakikalık 'fark' ölçülebilir, sonra 11 + 4 = 15. Bir kum saatini yarıda çevirmek, akmış kumu geri yükleyerek 'kalan süreyi' kopyalamak demektir.",
  h:"Kum saatleri Avrupa'da 14. yüzyıldan beri kullanılır; denizcilikte geminin hızını ölçmek için (ünlü 'knot' ölçümü) vazgeçilmezdi. Kum saati bulmacaları ise 20. yüzyıl bulmaca kitaplarının ve Martin Gardner'ın köşe yazılarının sevilen konularındandır.",
  n:"7 ve 11 dakikalık kum saatleriyle, belli bir noktadan sonra her tam dakika ölçülebilir!"},

 {t:"Hanoi Kulesi",lv:L3,nw:1,bg:"temple",
  act:[["hanoi",160,134,110,"none"],["monk",50,134,56,"bob"],["monk",270,134,56,"bob",1,.4]],
  in:["Hindistan'da, Benares'teki büyük bir tapınakta keşişler gece gündüz çalışıyor.","Üç elmas çubuk ve 64 altın disk var. Diskler tek tek taşınıyor; büyük hiçbir zaman küçüğün üstüne konmuyor.","Efsaneye göre son disk yerine konduğunda dünya sona erecek!"],
  q:"Tüm kuleyi en sağ direğe taşı. Bir seferde bir disk taşınır ve büyük disk küçüğün üstüne konamaz. 4 diskle dene!",
  g:(el,api)=>hanoi(el,api,4),
  a:"15 hamle (2⁴ − 1)",
  s:["Üstteki 3 diski ortadaki direğe taşı (bu da bir mini Hanoi: 7 hamle).","En büyük diski sağdaki direğe taşı (1 hamle).","Ortadaki 3 diski sağdaki direğe, en büyüğün üstüne taşı (yine 7 hamle).","Toplam: 7 + 1 + 7 = 15 hamle.","Pratik ipucu: En küçük diski hep aynı yönde (sol→orta→sağ→sol...) döndür; aradaki hamlelerde küçük diske dokunmadan yapılabilen tek hamleyi yap."],
  w:"Bu bir <b>özyineleme</b> (recursion) örneğidir: n diski taşımak için önce n−1 diski kenara al, en büyüğü taşı, sonra n−1 diski geri koy. Hamle sayısı H(n) = 2·H(n−1) + 1 → H(n) = 2ⁿ − 1. Bilgisayar bilimi derslerinde özyinelemeyi anlatmanın en klasik yoludur.",
  h:"Bulmacayı 1883'te Fransız matematikçi <b>Édouard Lucas</b>, 'N. Claus de Siam' takma adıyla (bu isim 'Lucas d'Amiens'in harflerinin yer değiştirmiş halidir) bir oyuncak olarak piyasaya sürdü. Brahma tapınağı efsanesini de pazarlamak için kendisinin uydurduğu düşünülür.",
  n:"64 disk için 2⁶⁴ − 1 ≈ 18,4 kentilyon hamle gerekir. Saniyede bir hamleyle bu ~585 milyar yıl sürer — evrenin yaşının 40 katından fazla. Dünya güvende! 😄"},

 {t:"Kuleye Hapsolan Kral",lv:L4,nw:1,bg:"castle",
  act:[["castle",80,136,120,"none"],["king",190,136,54,"shake"],["queen",232,136,48,"bob",0,.3],["prince",268,136,40,"bob",0,.6],["stone",302,136,30,"none"]],
  in:["Bir isyan çıktı ve kral, kraliçe ve küçük prens kulenin tepesine hapsedildi!","Pencerenin önünde bir makara ve iki sepet var: biri inerken öbürü çıkıyor.","Ağır sepet çok hızlı düşerse içindeki yaralanır. Yanlarında 75 kiloluk bir taş da var..."],
  q:"Kral (195 kg), kraliçe (105), prens (90) ve bir taş (75) kulede hapis. Makaradaki iki sepetten ağır olan iner, hafif olan çıkar. İçinde insan varsa fark en çok 15 kg olmalı. Kraliyet ailesini aşağı indir!",
  g:tower,
  a:"9 iniş",
  s:["Taş iner (boş sepet çıkar; sepette insan olmadığı için hız sorun değil).","Prens iner, taş çıkar (90 − 75 = 15 ✓).","Kraliçe iner, prens çıkar (105 − 90 = 15 ✓).","Taş iner (boş sepet çıkar).","Prens iner, taş çıkar (15 ✓).","Kral iner; kraliçe ve taş birlikte çıkar (195 − 180 = 15 ✓) — en zekice hamle!","Taş iner.","Kraliçe iner, prens çıkar (15 ✓).","Prens iner, taş çıkar (15 ✓). Bütün aile aşağıda, taş kulede kaldı!"],
  w:"Taş, bir <b>karşı ağırlık</b> görevi görür: insanları yavaşça indirmek için defalarca inip çıkar. Ağırlıklar arasındaki fark hep 15 kg olacak şekilde seçilmiş: 75, 90, 105 ve 180 (105+75), 195. En zor an kralın inişidir; çünkü onu dengeleyecek tek kombinasyon kraliçe + taş'tır. Kraliçeyi önceden aşağı indirip sonra geri çıkarmak gerekir.",
  h:"Bu bulmaca, <i>Alice Harikalar Diyarında</i>'nın yazarı ve matematikçi <b>Lewis Carroll</b>'un (Charles L. Dodgson, 1832–1898) defterlerindeki 'tutsak kraliçe' bulmacasından uyarlanmıştır.",
  n:"Gerçek asansörler de aynı fikirle çalışır: kabin ağır bir karşı ağırlıkla dengelenir, böylece motor çok daha az güç harcar."}
];

const PAR=[
 {t:"Yalancı Paradoksu",lv:L1,bg:"stage",txt:"\"Bu cümle yanlıştır.\"",
  act:[["liar",160,142,90,"shake"],["bubble",240,74,46,"float"]],
  in:["Antik Yunan'da, Girit adasından bir adam meydana çıkıp bağırdı:","\"Bütün Giritliler yalancıdır!\"","Peki o da Giritli... Doğru mu söylüyor, yalan mı?"],
  q:"Tahtada şu yazıyor: \"Bu cümle yanlıştır.\" Bu cümle doğru mu, yanlış mı?",g:liarX,
  o:["Doğru","Yanlış","Tutarlı bir değer verilemez","Hem doğru hem yanlış, sorun yok"],c:2,a:"Tutarlı bir doğruluk değeri verilemez",
  s:["Cümle doğruysa, söylediği şey geçerli olmalı: yani yanlış olmalı. Çelişki!","Cümle yanlışsa, 'yanlıştır' iddiası yanlış, yani cümle doğru olmalı. Yine çelişki!","Sonuç: cümleye 'doğru' ya da 'yanlış' etiketi tutarlı biçimde verilemez."],
  w:"Sorunun kaynağı <b>öz-gönderme</b>dir: cümle kendi doğruluğu hakkında konuşuyor. Günlük dilde bu masum görünür ama mantık sistemlerinde felaket yaratır. Alfred Tarski'nin çözümü bir 'dil hiyerarşisi'dir: bir dil kendi doğruluğundan bahsedemez; bunu ancak bir üst dil (üst dil) yapabilir. Bazı modern mantıkçılar (paraconsistent logic) ise 'hem doğru hem yanlış' cümlelere izin veren sistemler kurar.",
  h:"MÖ 6. yüzyılda Giritli filozof <b>Epimenides</b>'e atfedilen 'Bütün Giritliler yalancıdır' sözü bu paradoksun ataları arasında sayılır (bu söz İncil'de, Pavlus'un Titus'a Mektubu'nda bile geçer). Asıl katı biçimini MÖ 4. yüzyılda Miletoslu <b>Eubulides</b> verdi: 'Ben şu an yalan söylüyorum.' 1931'de <b>Kurt Gödel</b> benzer bir fikirle 'Bu önerme kanıtlanamaz' cümlesini matematiksel olarak kurdu ve ünlü <b>eksiklik teoremi</b>ni kanıtladı. <b>Alfred Tarski</b> 1933'te doğruluğun tanımlanamazlığı teoremiyle konuyu derinleştirdi.",
  n:"Ortaçağ'da filozoflar bu tür cümlelere 'insolubilia' (çözülemezler) adını vermişti."},

 {t:"Aşil ve Kaplumbağa",lv:L1,bg:"track",
  act:[["achilles",50,132,62,"walk"],["turtle",220,132,42,"bob"],["flag",296,132,46,"tilt"]],
  in:["Truva savaşının en hızlı kahramanı Aşil, bir kaplumbağayla yarışacak.","Centilmenlik edip kaplumbağaya 100 metre avans veriyor.","Ama filozof Zenon araya giriyor: \"Aşil onu asla yakalayamaz!\""],
  q:"Kaplumbağa 100 m önde, Aşil 10 kat hızlı. Aşil 100 m'ye varınca kaplumbağa 10 m ilerlemiş, oraya varınca 1 m... Asla yakalayamaz mı?",g:achX,
  o:["Asla yakalayamaz","100 m'de yakalar","Yaklaşık 111,1 m'de yakalar","200 m'de yakalar"],c:2,a:"≈111,1 m'de yakalar",
  s:["Mesafeler: 100 + 10 + 1 + 0,1 + 0,01 + ... Bu sonsuz bir toplam ama sonucu sonludur.","Geometrik seri formülü: a / (1 − r) = 100 / (1 − 1/10) = 111,11... m.","Süreler de aynı oranla küçülür ve sonlu bir zamana toplanır.","Sonsuz sayıda adım, sonsuz zaman demek değildir!"],
  w:"Zenon'un hilesi, hareketi sonsuz sayıda parçaya bölmek ve 'sonsuz parça = sonsuz süre' sezgisini kullanmaktır. Oysa parçalar giderek küçülüyorsa toplamları sonlu olabilir. Bu fikir ancak 17. yüzyılda kalkülüsle ve 19. yüzyılda <b>limit</b> kavramının kesin tanımıyla matematiksel olarak sağlam temele oturdu. Bazı filozoflar hâlâ paradoksun 'fiziksel' tarafını (uzay ve zaman sonsuz bölünebilir mi?) tartışır.",
  h:"Elealı <b>Zenon</b> (MÖ ~490–430), hocası Parmenides'in 'değişim ve hareket bir yanılsamadır' görüşünü savunmak için bu paradoksları üretti. Zenon'un kendi yazıları kayboldu; paradokslarını <b>Aristoteles</b>'in <i>Fizik</i> adlı eserinden (MÖ 4. yüzyıl) öğreniyoruz. Matematiksel çözüm, <b>Isaac Newton</b> ve <b>Gottfried Leibniz</b>'in 1600'lerin sonunda geliştirdiği kalkülüs ve <b>Augustin-Louis Cauchy</b>'nin 1821'de verdiği kesin limit tanımı ile tamamlandı.",
  n:"Zenon'un 'Ok' paradoksu da ünlüdür: Uçan bir ok her an belli bir yerde durur; öyleyse ne zaman hareket eder?"},

 {t:"Theseus'un Gemisi",lv:L2,bg:"sea",
  act:[["ship",130,138,96,"bob"],["hammer",240,96,36,"tilt"],["plank",280,130,38,"float"]],
  in:["Atinalılar, efsanevi kahraman Theseus'un gemisini yüzyıllarca limanda korudu.","Bir tahta çürüdükçe yenisiyle değiştirdiler... sonra bir tane daha... bir tane daha...","Bir gün gemide tek bir orijinal tahta kalmadı."],
  q:"Geminin tahtaları birer birer değiştirildi; hiç orijinal parça kalmadı. Hâlâ aynı gemi mi? Ya eski tahtalarla ikinci bir gemi yapılırsa?",g:shipX,
  o:["Kesinlikle aynı gemi","Kesinlikle başka gemi","Cevap 'aynılık'ı nasıl tanımladığımıza bağlı","Eski tahtalardan yapılan, tartışmasız"],c:2,a:"Tanıma bağlı",
  s:["<b>Madde görüşü:</b> Bir şeyin kimliği onu oluşturan parçalardır → eski tahtalardan yapılan gemi gerçek Theseus gemisidir.","<b>Süreklilik görüşü:</b> Kimlik, kesintisiz bir tarih ve işlevdir → limanda yüzen, yavaş yavaş yenilenen gemi gerçektir.","<b>Dörtboyutçuluk:</b> Gemi zaman içinde uzanan bir 'olay'dır; iki gemi aynı geçmişi paylaşan iki ayrı dal olabilir.","Paradoks, 'aynı' kelimesinin günlük dilde birden fazla anlama geldiğini ortaya koyar."],
  w:"Bu bir mantık hatası değil, kavramsal bir bulmacadır: 'aynılık' (özdeşlik) dediğimiz şeyin net bir tanımı yoktur. Hukukta, tarihte ve teknolojide gerçek sonuçları vardır: tamamen restore edilmiş bir tarihi eser 'orijinal' midir? Tüm üyeleri değişmiş bir müzik grubu aynı grup mudur? Parçaları sürekli güncellenen bir yazılım?",
  h:"Hikâyeyi ilk kez Yunan tarihçi <b>Plutarkhos</b> (MS ~46–120), <i>Paralel Yaşamlar</i> kitabındaki Theseus biyografisinde anlattı; Atinalıların gemiyi MÖ 3. yüzyıla kadar koruduğunu ve filozofların bunu 'büyüme meselesi' örneği olarak tartıştığını yazdı. 1655'te İngiliz filozof <b>Thomas Hobbes</b> <i>De Corpore</i> adlı eserinde ikinci gemi fikrini (eski tahtalardan yeniden inşa) ekleyerek paradoksu keskinleştirdi. <b>John Locke</b> 1690'da kişisel kimlik üzerine benzer sorular sordu.",
  n:"İnsan vücudundaki hücrelerin büyük kısmı yıllar içinde yenilenir. 10 yıl önceki sen, sen misin?"},

 {t:"Berber Paradoksu",lv:L2,bg:"room",
  act:[["pole",44,134,66,"none"],["barber",160,142,90,"bob"],["razor",250,100,36,"tilt"]],
  in:["Küçük bir köyde tek bir berber yaşıyor ve kendine katı bir kural koymuş:","\"Kendini tıraş etmeyen herkesi ben tıraş ederim. Kendini tıraş edenleri ise asla!\"","Bir sabah aynaya bakıyor ve sakalının uzadığını görüyor..."],
  q:"Köyün berberi, kendini tıraş ETMEYEN herkesi tıraş ediyor; kendini tıraş edenleri asla. Berber kendini tıraş eder mi?",g:barberX,
  o:["Eder","Etmez","Böyle bir berber var olamaz","Bazı günler eder"],c:2,a:"Böyle bir berber var olamaz",
  s:["Kendini tıraş ederse: kural 'kendini tıraş edeni tıraş etmem' der → etmemeli.","Kendini tıraş etmezse: kural 'kendini tıraş etmeyeni ben tıraş ederim' der → etmeli.","Her iki yol çelişkiye çıktığına göre, böyle bir kurala uyan bir berber mantıksal olarak var olamaz."],
  w:"Berber hikâyesi aslında matematiğin temellerini sarsan <b>Russell paradoksu</b>nun halk versiyonudur: 'Kendini eleman olarak içermeyen tüm kümelerin kümesi' R olsun. R kendini içerir mi? İçerirse içermemeli, içermezse içermeli! Bu, 'her tanım bir küme oluşturur' sanan saf küme kuramının çökmesi demekti. Çözüm, kümelerin nasıl kurulabileceğini kısıtlayan aksiyomlardır (ZF aksiyomları).",
  h:"İngiliz filozof ve matematikçi <b>Bertrand Russell</b> (1872–1970) paradoksu 1901'de keşfetti. 16 Haziran 1902'de, aritmetiği mantığa dayandırmak için ömrünü vermiş Alman mantıkçı <b>Gottlob Frege</b>'ye bir mektup yazdı. Frege, kitabının ikinci cildi baskıdayken bu mektubu okudu ve sona şu acı notu ekledi: 'Bir bilim insanının başına, eseri tamamlandıktan sonra temelinin çöktüğünü görmekten daha kötü bir şey gelemez.' <b>Ernst Zermelo</b> 1908'de bu sorunu aşan aksiyomları önerdi. Russell berber benzetmesini 1918'deki derslerinde kullandı.",
  n:"Russell 1950'de Nobel Edebiyat Ödülü'nü kazandı ve 97 yaşına kadar yaşadı!"},

 {t:"Doğum Günü Paradoksu",lv:L2,bg:"party",
  act:[["cake",160,138,66,"pulse"],["balloon",40,96,46,"float"],["balloon",286,90,46,"float",0,.6],["boy",96,138,46,"bob"],["girl",226,138,46,"bob",1,.3]],
  in:["Bir sınıfta 23 öğrenci var. Öğretmen soruyor:","\"Sizce aynı gün doğmuş iki kişi olma ihtimali nedir?\"","Çoğu öğrenci gülüyor: \"Yılda 365 gün var, çok düşüktür!\" Gerçekten öyle mi?"],
  q:"Bir odada en az kaç kişi olursa, ikisinin aynı gün doğmuş olma olasılığı %50'yi geçer?",g:bdayX,
  o:["23","57","183","366"],c:0,a:"23 kişi",
  s:["Tersini hesaplamak daha kolay: herkesin doğum günü FARKLI olsun.","1. kişi herhangi bir gün (365/365), 2. kişi kalan 364 günden biri (364/365), 3. kişi 363/365...","23 kişi için çarpım: (365·364·...·343) / 365²³ ≈ 0,493.","Yani en az bir çakışma olasılığı ≈ 1 − 0,493 = %50,7.","57 kişide %99'u, 70 kişide %99,9'u geçer!"],
  w:"Sezgimiz yanılıyor çünkü 'benim doğum günümü paylaşan biri var mı?' diye düşünüyoruz (o olasılık 23 kişide sadece %6). Oysa soru <b>herhangi iki kişi</b> hakkında. 23 kişide C(23,2) = 253 farklı ikili var ve her ikilinin çakışma şansı var. İkili sayısı kişi sayısının karesiyle büyür; olasılık da bu yüzden hızla tırmanır.",
  h:"Problemin ilk kez Avusturyalı matematikçi <b>Richard von Mises</b> tarafından 1939'da yayımlandığı kabul edilir; ancak İngiliz matematikçi <b>Harold Davenport</b>'un 1927'de arkadaşları arasında bunu sorduğu da anlatılır. Bugün bilgisayar güvenliğinde '<b>doğum günü saldırısı</b>' adıyla bilinir: şifreleme özet (hash) fonksiyonlarında çakışma bulmanın beklenenden çok daha kolay olduğunu gösterir.",
  n:"Bir futbol maçında sahada 23 kişi vardır (22 oyuncu + hakem). 2014 Dünya Kupası'ndaki takımların yaklaşık yarısında aynı doğum gününü paylaşan oyuncular bulundu!"},

 {t:"Monty Hall",lv:L3,bg:"studio",
  act:[["door",70,134,76,"pulse"],["door",160,134,76,"bob",0,.3],["goat",246,134,58,"shake"],["host",296,140,66,"bob",1]],
  in:["Işıklar, kameralar, alkışlar! Büyük yarışmanın finalindesin.","Üç kapı var: birinin ardında yepyeni bir araba, ikisinin ardında keçi.","Sen bir kapı seçiyorsun... ve sunucu gülümseyerek başka bir kapıyı açıp keçi gösteriyor. \"Kapını değiştirmek ister misin?\""],
  q:"Üç kapıdan birinde araba, ikisinde keçi var. Bir kapı seçiyorsun, sunucu (arabanın yerini bilir) başka bir kapıdan keçi gösteriyor. Değiştirmeli misin?",g:montyX,
  o:["Fark etmez, %50-%50","Değiştirmeliyim","Değiştirmemeliyim","Sunucunun ruh haline bağlı"],c:1,a:"Değiştir! Kazanma şansı 2/3",
  s:["İlk seçiminin araba olma olasılığı 1/3. Sunucu ne yaparsa yapsın bu değişmez.","Arabanın öbür iki kapıdan birinde olma olasılığı 2/3.","Sunucu arabanın yerini <b>bildiği</b> için her zaman keçili kapıyı açar. Böylece o 2/3'lük olasılığın tamamı açılmamış tek kapıya 'toplanır'.","Değiştirirsen 2/3, kalırsan 1/3 kazanırsın.","Sezgi için: 100 kapı düşün. Birini seçtin, sunucu kalan 99'un 98'ini açıp keçi gösterdi. Sence araba senin kapında mı, yoksa sunucunun özenle kapalı bıraktığı tek kapıda mı?"],
  w:"Paradoksun kalbi, sunucunun <b>bilgisi</b>dir. Sunucu kapıyı rastgele açsaydı ve şans eseri keçi çıksaydı, olasılıklar gerçekten %50-%50 olurdu. Ama sunucu kuralları gereği hep keçi gösterir; bu davranış sana yeni bilgi verir. İnsan beyni 'iki kapı kaldı, şans eşit' diye düşünmeye programlanmıştır; koşullu olasılık (Bayes teoremi) ise başka bir şey söyler.",
  h:"Adını 1963'te başlayan Amerikan TV yarışması <i>Let's Make a Deal</i>'in sunucusu <b>Monty Hall</b>'dan (1921–2017) alır. Problemi ilk kez istatistikçi <b>Steve Selvin</b> 1975'te <i>The American Statistician</i> dergisine yazdığı mektupta ortaya koydu. Asıl fırtına 9 Eylül 1990'da koptu: dünyanın en yüksek IQ'suna sahip kişi olarak Guinness'e giren <b>Marilyn vos Savant</b>, <i>Parade</i> dergisindeki köşesinde 'değiştirin' dedi. Aralarında yüzlerce doktoralı akademisyenin de bulunduğu yaklaşık 10.000 kişi ona 'yanılıyorsunuz' diye mektup yazdı. Ünlü matematikçi <b>Paul Erdős</b> bile ancak bilgisayar simülasyonunu görünce ikna oldu.",
  n:"Yapılan deneylerde güvercinler, birkaç yüz denemeden sonra kapı değiştirmeyi öğreniyor; insanlar ise çoğu zaman öğrenemiyor!"},

 {t:"Hilbert'in Oteli",lv:L3,bg:"hotel",
  act:[["hotel",110,138,116,"none"],["suitcase",236,138,40,"walk"],["infinity",236,64,52,"pulse"],["runner",280,138,50,"bob",1]],
  in:["Galaksinin en büyük oteli: Hilbert Oteli. Sonsuz sayıda odası var!","Bu gece her oda dolu; tabelada 'BOŞ ODA YOK' yazıyor.","Gece yarısı kapıya bavuluyla bir yolcu geliyor..."],
  q:"Sonsuz odalı otel tamamen dolu. Kapıya yeni bir misafir geliyor. Ona oda verilebilir mi?",g:hilbertX,
  o:["Hayır, otel dolu","Evet: herkes n → n+1 odaya geçer","Sadece biri çıkarsa","Sonsuz otelde hep boş oda vardır"],c:1,a:"Evet, herkes bir oda kaydırılır",
  s:["Resepsiyonist anons yapar: 'n numaralı odadaki misafir, n+1 numaralı odaya geçsin.'","Sonsuz oda olduğu için kimse açıkta kalmaz: 1→2, 2→3, 1000→1001...","1 numaralı oda boşalır; yeni misafir oraya yerleşir.","Bonus: Sonsuz kişilik bir otobüs gelirse? Herkes 2n'ye geçer (1→2, 2→4, 3→6...). Tüm tek numaralı odalar — sonsuz tane — boşalır!","Süper bonus: Sonsuz sayıda sonsuz otobüs gelirse? Asal sayıların kuvvetleri kullanılarak onlar da yerleştirilebilir!"],
  w:"Sonlu dünyada 'dolu' demek 'yer yok' demektir. Ama sonsuz kümelerde bir parça bütün kadar büyük olabilir: çift sayılar, tüm doğal sayılar kadar 'çoktur', çünkü aralarında bire bir eşleme kurulabilir (n ↔ 2n). Cantor bu tür sonsuzluğa 'sayılabilir sonsuzluk' (ℵ₀, alef-sıfır) adını verdi. Şaşırtıcı olan: bazı sonsuzluklar daha büyüktür! Gerçek sayılar otele asla sığmaz.",
  h:"Alman matematikçi <b>David Hilbert</b> (1862–1943) bu düşünce deneyini 1924'te Göttingen'de verdiği bir derste anlattı. Hikâye, 1947'de fizikçi <b>George Gamow</b>'un ünlü popüler bilim kitabı <i>Bir, İki, Üç... Sonsuz</i> ile dünyaya yayıldı. Fikirlerin temeli, 1870'ler ve 1890'lar arasında sonsuzlukları karşılaştırmayı icat eden <b>Georg Cantor</b>'a (1845–1918) aittir. Cantor'un fikirleri döneminde o kadar tepki çekti ki, hocası Kronecker ona 'gençliği yozlaştıran kişi' dedi. Hilbert ise ona sahip çıkarak 'Kimse bizi Cantor'un bize yarattığı cennetten kovamayacak!' dedi.",
  n:"∞ + 1 = ∞ ve ∞ + ∞ = ∞, ama 2^∞ > ∞ (Cantor'un köşegen kanıtı)."},

 {t:"Simpson Paradoksu",lv:L3,bg:"hospital",
  act:[["hospital",80,138,92,"none"],["hospital",240,138,92,"none"],["chart",160,84,56,"pulse"]],
  in:["Şehirde iki hastane var ve sen ameliyat olacaksın.","Gazete manşeti: \"B Hastanesinde iyileşme oranı %94, A'da sadece %73!\"","Kararını vermeden önce bir de rakamların içine bakalım..."],
  q:"A Hastanesi hem hafif hem ağır hastalarda B'den daha başarılı. Toplamda ise B daha başarılı görünüyor. Bu mümkün mü?",g:simpsonX,
  o:["Hayır, matematiksel olarak imkânsız","Evet, grupların büyüklükleri farklıysa mümkün","Sadece veri yanlışsa","Sadece hasta sayıları eşitse"],c:1,a:"Evet, mümkün",
  s:["A Hastanesi: ağır hastalar 900'de 630 (%70), hafif hastalar 100'de 99 (%99) → toplam 1000'de 729 (%72,9).","B Hastanesi: ağır hastalar 100'de 60 (%60), hafif hastalar 900'de 882 (%98) → toplam 1000'de 942 (%94,2).","A her iki grupta da daha başarılı! Ama A'nın hastalarının %90'ı ağır, B'nin ise %90'ı hafif vaka.","Toplam oran, hasta karışımının farkını gizliyor. Doğru karar için gruplara bakmalısın: ağır hastaysan A'yı seç!"],
  w:"Toplam oran, grup oranlarının ağırlıklı ortalamasıdır; ağırlıklar (grup büyüklükleri) farklıysa sıralama tersine dönebilir. Bu, gizli bir '<b>karıştırıcı değişken</b>'in (burada hastalığın ağırlığı) sonucu nasıl çarpıtabileceğini gösterir. İstatistikte 'korelasyon nedensellik değildir' uyarısının en güçlü örneklerinden biridir.",
  h:"Adını, olguyu 1951'de bir makalede açıklayan İngiliz istatistikçi <b>Edward H. Simpson</b>'dan (1922–2019) alır; Simpson İkinci Dünya Savaşı'nda Bletchley Park'ta Alman şifrelerini çözen ekipteydi. Etkiyi daha önce <b>Karl Pearson</b> (1899) ve <b>Udny Yule</b> (1903) de fark etmişti. En ünlü gerçek örnek: 1973'te Berkeley Üniversitesi'nin kadınlara karşı ayrımcılıkla suçlanması. Genel kabul oranında erkekler öndeydi, ama bölüm bölüm bakınca çoğu bölümde kadınlar biraz daha avantajlıydı; kadınlar sadece daha rekabetçi bölümlere başvuruyordu (Bickel ve arkadaşları, <i>Science</i>, 1975). 1986'daki bir böbrek taşı çalışması da benzer bir tablo ortaya koydu.",
  n:"COVID-19 döneminde bazı ülkeler arasındaki ölüm oranı karşılaştırmalarında da yaş dağılımı yüzünden Simpson paradoksu görüldü."},

 {t:"Sürpriz Sınav",lv:L4,bg:"class",
  act:[["teacher",56,142,80,"bob"],["board",160,104,90,"none"],["student",264,142,70,"shake"],["calendar",160,152,30,"pulse"]],
  in:["Cuma günü öğretmen sınıfa duyurdu:","\"Gelecek hafta bir gün sürpriz sınav yapacağım. O sabaha kadar hangi gün olduğunu bilemeyeceksiniz!\"","Sınıfın en zeki öğrencisi gülümsedi: \"Hocam, bu imkânsız!\""],
  q:"Öğretmen: \"Gelecek hafta bir gün sürpriz sınav olacak.\" Öğrenci geriye doğru akıl yürütüp \"hiçbir gün olamaz\" der. Sınav Çarşamba olur. Öğrenci şaşırır mı?",g:examX,
  o:["Hayır, sınav imkânsızdı","Evet, öğrencinin akıl yürütmesi hatalıydı","Öğretmen yalan söylemiş olur","Sadece Cuma olsaydı şaşırırdı"],c:1,a:"Evet, şaşırır",
  s:["Öğrencinin mantığı: Cuma olamaz, çünkü Perşembe akşamı sınav olmadıysa Cuma olacağını bilirdim. Cuma elendiyse Perşembe de son gün olur ve bilirdim... Böylece tüm günleri eler.","Ama Cuma'yı elemek için öğretmenin duyurusuna <b>güveniyor</b>; sonra aynı duyurunun hiç gerçekleşemeyeceği sonucuna varıyor. Kendi varsayımını çürüten bir zincir!","Duyuruya güvenmiyorsa Cuma'yı eleyemez; güveniyorsa, 'sınav olmayacak' sonucuna varamaz.","Sonuçta 'sınav olmaz' diye inandığı için Çarşamba günü gerçekten beklemez → sınav sürpriz olur ve öğretmen haklı çıkar."],
  w:"Paradoks, '<b>bilmek</b>' kavramının kendine gönderme yapan bir duyuruyla birleştiğinde nasıl çuvalladığını gösterir. Duyuru aslında 'Bu duyurudan yola çıkarak sınav gününü önceden çıkaramayacaksınız' der: tıpkı yalancı paradoksu gibi kendi hakkında konuşur. Filozoflar hâlâ hatanın tam olarak nerede olduğunda uzlaşamamıştır; epistemik mantık (bilgi mantığı) bu tartışmalardan doğdu.",
  h:"Paradoks 1940'larda ortaya çıktı. Bir hikâyeye göre İkinci Dünya Savaşı sırasında İsveç radyosunda 'gelecek hafta sürpriz bir sivil savunma tatbikatı yapılacak' duyurusundan esinlenildi. Felsefe literatürüne <b>D. J. O'Connor</b>'ın 1948'de <i>Mind</i> dergisindeki makalesiyle girdi. Ünlü mantıkçı <b>W. V. O. Quine</b> 1953'te öğrencinin hatasını açıklayan bir yazı yayımladı. <b>Martin Gardner</b> 1963'te bunu Scientific American köşesinde 'beklenmedik idam' (unexpected hanging) versiyonuyla anlattı.",
  n:"İdam versiyonunda yargıç mahkuma 'gelecek hafta beklemediğin bir gün asılacaksın' der; mahkum 'o halde asılamam' diye sevinir... Çarşamba cellat kapıyı çalar."},

 {t:"İki Zarf Paradoksu",lv:L4,bg:"felt",
  act:[["envelope",100,128,66,"tilt"],["envelope",220,128,66,"float",0,.4],["money",160,74,40,"pulse"]],
  in:["Bir televizyon programında önüne iki kapalı zarf konuyor.","Birinde diğerinin tam iki katı para var. Birini seçip açıyorsun: 100 TL!","Sunucu soruyor: \"Öbür zarfla değiştirmek ister misin?\" Matematik sana 'değiştir!' diye fısıldıyor gibi..."],
  q:"Bir zarfta diğerinin 2 katı para var. Açtın: 100 TL. Öbürü 50 ya da 200; beklenen 125 > 100, değiştir! Ama aynı mantıkla sonsuza kadar değiştirmen gerekir... Hata nerede?",g:envX,
  o:["Hata yok, değiştirmek kazandırır","%50-%50 varsayımı her miktar için geçerli olamaz; değiştirmek ortalamada kazandırmaz","Zarfı açmak şansı değiştirir","Hep ilk zarfı tutmak kazandırır"],c:1,a:"Değiştirmek beklentiyi artırmaz",
  s:["Yanlış akıl yürütme: 'Elimde A var. Öbürü %50 ihtimalle A/2, %50 ihtimalle 2A. Beklenen = 1,25A > A → değiştir!' Bu her A için geçerli olduğuna göre zarfı açmadan bile değiştirmeli, sonra yine değiştirmeli... Saçma!","Doğru bakış: Zarflarda X ve 2X olsun. Elindeki X ise değiştirince +X kazanırsın; 2X ise −X kaybedersin. Ortalama kazanç: 0.","Hata: 'A' iki farklı senaryoda farklı değerleri temsil ediyor (birinde X, öbüründe 2X), ama aynı değişken gibi kullanılıyor.","Daha derin hata: 'Her miktar için %50-%50' varsaymak, sonsuz sayıda miktara eşit olasılık dağıtmak demektir. Böyle bir olasılık dağılımı matematiksel olarak var olamaz."],
  w:"Beklenen değer hesabı doğru bir araçtır ama yanlış olasılıklarla beslenirse saçma sonuçlar üretir. Gerçek hayatta para miktarlarının bir dağılımı vardır (örneğin programın bütçesi 10.000 TL'yi geçmez); bu dağılım bilinince, gördüğün miktara göre değiştirmek bazen akıllıca olabilir: 100 TL gördüysen belki, 10.000 gördüysen kesinlikle hayır!",
  h:"Belçikalı matematikçi <b>Maurice Kraitchik</b> (1882–1957) 1953'te bunun bir ön biçimini '<b>kravat paradoksu</b>' olarak yayımladı: iki adam, kimin kravatı daha pahalıysa onu öbürüne vereceği bir iddiaya girer ve ikisi de kazanma şansının avantajlı olduğunu düşünür. <b>Martin Gardner</b> 1982'de cüzdan versiyonunu popülerleştirdi. Bugünkü iki zarf biçimi 1989'da ekonomist <b>Barry Nalebuff</b> tarafından yayımlandı ve felsefe dergilerinde yüzlerce makaleye konu oldu.",
  n:"Bazı 'tuhaf' dağılımlarda (beklenen değeri sonsuz olanlar) paradoks daha da inatçı hale gelir ve hâlâ araştırılıyor."},

 {t:"Yığın Paradoksu",lv:L1,nw:1,bg:"desert",
  act:[["heap",160,138,120,"none"],["thinker",270,140,70,"bob",1]],
  in:["Çölün ortasında kocaman bir kum yığını duruyor: tam 10.000 tane.","Bir filozof bir tane kum alıyor ve soruyor: \"Hâlâ yığın mı?\"","\"Elbette!\" diyorsun. O da almaya devam ediyor... bir tane daha... bir tane daha..."],
  q:"10.000 kum tanesi bir yığındır. Bir tane eksiltirsen yine yığındır. Bunu tekrarlarsan sonunda 1 tane, hatta 0 tane de yığın olur mu?",g:heapX,
  o:["Evet, 1 tane de yığındır","Tam 100 tanede yığın olmaktan çıkar","Kesin bir sınır yok: 'yığın' bulanık bir kavram","Yığın diye bir şey yoktur"],c:2,a:"Kavram bulanık, keskin sınır yok",
  s:["Öncül 1: 10.000 kum tanesi bir yığındır. (Kesinlikle doğru görünüyor.)","Öncül 2: Bir yığından tek bir tane alınca hâlâ yığın kalır. (Bu da doğru görünüyor.)","Öncül 2'yi 9.999 kez uygularsan: '1 kum tanesi bir yığındır.' (Açıkça yanlış!)","Çözüm önerisi 1 — <b>Bulanık mantık:</b> 'Yığınlık' 0 ile 1 arasında bir derecedir. 10.000 tane %100 yığın, 50 tane belki %20.","Çözüm önerisi 2 — <b>Epistemik görüş:</b> Gerçekten keskin bir sınır vardır, ama biz onu asla bilemeyiz.","Çözüm önerisi 3 — <b>Süper-değerleme:</b> 'Yığın' kelimesinin kabul edilebilir her netleştirmesinde doğru olan cümleler doğrudur."],
  w:"Günlük dilimizdeki kelimelerin çoğu bulanıktır: uzun, kel, zengin, genç, kalabalık... Hiçbirinin 'tam şu noktada başlar' diyebileceğimiz bir sınırı yoktur. Bu paradoks, klasik 'ya doğru ya yanlış' mantığının bu kavramlarla neden zorlandığını gösterir. Hukukta da büyük önemi var: 'reşit olma yaşı' ya da 'hız sınırı' gibi kurallar bu bulanıklığı keyfi ama işe yarar bir çizgiyle keser.",
  h:"Paradoks, yalancı paradoksunun da sahibi olan Miletoslu <b>Eubulides</b>'e (MÖ 4. yüzyıl) atfedilir. Adı Yunanca 'soros' (yığın) kelimesinden gelir: sorites paradoksu. Eubulides'in 'kel adam' versiyonu da ünlüdür: Bir adamın tek bir saç teli düşerse kel olmaz... 1965'te Azerbaycan asıllı Amerikalı mühendis <b>Lotfi Zadeh</b> (1921–2017) 'bulanık kümeler' kuramını ortaya attı; bu kuram bugün çamaşır makinelerinden metro frenlerine kadar birçok teknolojide kullanılıyor.",
  n:"Japonya'daki Sendai metrosu 1987'de bulanık mantıkla çalışan fren sistemine geçti ve yolculuklar çok daha yumuşak hale geldi."},

 {t:"Büyükbaba Paradoksu",lv:L2,nw:1,bg:"space",
  act:[["rocket",80,128,80,"float"],["oldman",224,138,58,"bob",1],["oldwoman",268,138,58,"bob",1,.3]],
  in:["Yıl 2026. Garajında bir zaman makinesi icat ettin!","Meraklı bir fikir aklına geliyor: 1960'a gidip dedenle nineni tanıştıkları gün görmek...","Ama ya yanlışlıkla onların tanışmasını engellersen?"],
  q:"Zaman makinesiyle geçmişe gidip dedenle ninenin tanışmasını engellersen hiç doğmazsın; o zaman geçmişe kim gitti? Aşağıdakilerden hangisi paradoksu ortadan kaldırmak için önerilen bir çözümdür?",g:grandX,
  o:["Zaman yolculuğu yapan kişi hemen yaşlanır","Novikov: geçmiş tutarlı kalmalı, engelleyemezsin (ya da çoklu evren)","Geçmişe sadece hayvanlar gidebilir","Paradoks yok, sadece yalnız kalırsın"],c:1,a:"Novikov tutarlılığı veya çoklu evren",
  s:["Döngü: Engellersen doğmazsın → doğmadıysan geçmişe gidip engelleyemezsin → engellemediysen doğarsın → doğduysan gidip engellersin...","<b>Novikov öz-tutarlılık ilkesi:</b> Geçmiş zaten olmuştur ve değiştirilemez. Geçmişe gidersen, yaptığın her şey zaten tarihin bir parçasıydı; engelleme girişimin bir şekilde başarısız olur.","<b>Çoklu evren yorumu:</b> Geçmişe gitmek yeni bir zaman çizgisi dallandırır. Değişiklik o yeni dalda olur; senin geldiğin evren etkilenmez.","<b>Yasak yorumu:</b> Belki de geçmişe yolculuk fizik yasalarınca tamamen yasaktır (Hawking'in 'kronoloji koruma' varsayımı)."],
  w:"Bu paradoks bir 'neden-sonuç döngüsü' problemidir: bir olay kendi nedenini ortadan kaldırıyor. Einstein'ın genel görelilik kuramı bazı egzotik durumlarda zaman döngülerine (kapalı zamansı eğriler) izin verir; bu yüzden fizikçiler bu paradoksu ciddiye alır. Paradoksun çözümü, fiziğin 'nedensellik' ve 'özgür irade' hakkında bize ne söylediğiyle ilgilidir.",
  h:"Paradoks, Fransız yazar <b>René Barjavel</b>'in 1943 tarihli romanı <i>Le Voyageur Imprudent</i>'da (Dikkatsiz Yolcu) ünlü biçimini kazandı. 1949'da <b>Kurt Gödel</b>, Einstein'ın denklemlerine zaman döngülerine izin veren bir çözüm bularak (dönen evren) konuyu fiziğe taşıdı. Amerikalı fizikçi <b>Hugh Everett</b> 1957'de 'çok dünyalar yorumu'nu önerdi. Rus astrofizikçi <b>Igor Novikov</b> 1980'lerin ortasında öz-tutarlılık ilkesini geliştirdi. <b>Stephen Hawking</b> 1992'de 'kronoloji koruma varsayımı'nı ortaya attı ve 2009'da sadece davetiyeleri parti sonrasında gönderdiği bir 'zaman yolcuları partisi' düzenledi: kimse gelmedi!",
  n:"'Geleceğe Dönüş' (1985) dallanan/değişen zaman çizgisini, 'Interstellar' (2014) ve 'Dark' dizisi ise Novikov tarzı tutarlı döngüleri kullanır."},

 {t:"Erkek mi Kız mı?",lv:L3,nw:1,bg:"party",
  act:[["boy",110,138,62,"bob"],["bubble",160,70,40,"float"],["girl",210,138,62,"bob",1,.3]],
  in:["Yeni komşun kapını çalıyor: \"Merhaba! İki çocuğum var.\"","Arkasından küçük bir oğlan koşarak geliyor: \"Bu benim oğlum!\"","Peki öbür çocuğun da erkek olma ihtimali nedir? Cevap, düşündüğünden daha ilginç..."],
  q:"Bir ailenin iki çocuğu var ve en az birinin erkek olduğunu biliyorsun. İkisinin de erkek olma olasılığı nedir?",g:kidsX,
  o:["1/2","1/3","1/4","2/3"],c:1,a:"1/3",
  s:["İki çocuklu bir ailede (büyük–küçük sırasıyla) dört eşit olası durum vardır: EE, EK, KE, KK.","'En az biri erkek' bilgisi sadece KK'yi eler: EE, EK, KE kalır.","Bu üç eşit olası durumdan sadece biri EE: olasılık 1/3.","Dikkat! Soru 'Büyük çocuk erkek' diye sorulsaydı EE ve EK kalırdı → cevap 1/2 olurdu.","Kapıdaki örnekte olduğu gibi 'rastgele bir çocuğu gördün ve erkekti' durumu da 1/2 verir! Bilgiyi nasıl edindiğin cevabı değiştirir."],
  w:"Bu paradoks, koşullu olasılıkta '<b>bilginin nasıl elde edildiği</b>'nin önemini gösterir. 'En az biri erkek' bilgisi aileler hakkında genel bir filtre iken, 'şu belirli çocuk erkek' bilgisi tek bir çocuk hakkındadır. Benzer bir tuzak 'Salı günü doğmuş bir oğlum var' sorusunda daha da çarpıcıdır: o zaman cevap 13/27 olur!",
  h:"Amerikalı bilim yazarı <b>Martin Gardner</b> (1914–2010) problemi 1959'da <i>Scientific American</i> dergisindeki ünlü 'Matematiksel Oyunlar' köşesinde yayımladı. Sonra problemin aslında belirsiz ifade edildiğini kabul etti: bilginin nasıl elde edildiğine bağlı olarak cevap 1/3 ya da 1/2 olabilir. 2010'da bulmaca tasarımcısı <b>Gary Foshee</b>'nin 'Salı günü doğmuş oğul' versiyonu bir Gardner anma toplantısında sorularak yeniden tartışma başlattı.",
  n:"Gardner 25 yıl boyunca bu köşeyi yazdı ve birçok genç kişiyi matematikçi olmaya ikna ettiği söylenir."},

 {t:"Braess Paradoksu",lv:L3,nw:1,bg:"city",
  act:[["car",60,140,40,"walk"],["carb",130,146,40,"walk",0,.8],["cone",260,140,46,"tilt"]],
  in:["Şehirdeki trafik dayanılmaz hale geldi: evden işe 65 dakika!","Belediye müjdeyi verdi: iki yolu birbirine bağlayan yepyeni, süper hızlı bir kısayol açılıyor.","Herkes sevinçli. Peki gerçekten işe yarayacak mı?"],
  q:"Şehre yeni ve bedava (0 dakikalık) bir kısayol eklendi. Herkes kendi süresini kısaltmaya çalışıyor. Sonuç ne olur?",g:braessX,
  o:["Herkes daha hızlı varır","Hiçbir şey değişmez","Herkes daha YAVAŞ varır","Sadece kısayolu kullananlar yavaşlar"],c:2,a:"Herkes yavaşlar (65 → 80 dk)",
  s:["İki rota var: Üst (trafiğe bağlı yol + sabit 45 dk) ve Alt (sabit 45 dk + trafiğe bağlı yol). Trafiğe bağlı yollar araç/100 dakika sürer.","Kısayol yokken 4000 araç ikiye bölünür: 2000/100 + 45 = 65 dakika.","Kısayol (0 dk) açılınca: trafiğe bağlı yol en kötü durumda 4000/100 = 40 dk, yani 45 dk'lık sabit yoldan her zaman iyi. Herkes 'trafiğe bağlı → kısayol → trafiğe bağlı' rotasını seçer.","Sonuç: 40 + 0 + 40 = 80 dakika! Herkes 15 dakika kaybetti.","Kimse tek başına rotasını değiştirerek kazanamaz (Nash dengesi). Kısayolu kapatmak herkesi hızlandırır."],
  w:"Herkes <b>kendi</b> çıkarı için en iyisini yaptığında toplum için kötü bir sonuç çıkabilir. Bu, oyun kuramındaki '<b>Nash dengesi</b>' ile 'sosyal optimum' arasındaki farktır (mahkum ikilemiyle aynı aileden). Sadece trafikte değil; elektrik şebekelerinde, internet veri ağlarında ve hatta ekolojide (besin zincirleri) görülür.",
  h:"Alman matematikçi <b>Dietrich Braess</b> (1938–) bunu 1968'de bir makalede kanıtladı. Gerçek örnekler: 1969'da Stuttgart'ta yeni bir yol açılınca trafik kötüleşti ve yol kapatılınca düzeldi. 1990'da New York'ta, Dünya Günü nedeniyle 42. Cadde kapatıldığında trafiğin beklenenin aksine akıcılaştığı gözlemlendi. 2005'te Seul'de Cheonggyecheon otoyolu yıkılıp yerine bir dere parkı yapıldığında, şehir merkezindeki trafik hızlandı.",
  n:"1991'de Joel Cohen ve Paul Horowitz, yayların ve iplerin oluşturduğu mekanik bir düzenekte bir ipi kesmenin bir ağırlığı aşağı değil YUKARI kaldırdığını gösterdi: aynı paradoksun mekanik versiyonu!"},

 {t:"Parrondo Paradoksu",lv:L4,nw:1,bg:"casino",
  act:[["slot",110,138,84,"shake"],["coin",210,100,40,"spin"],["coin",252,124,36,"spin",0,.5]],
  in:["Las Vegas'ta iki yeni oyun makinesi var: A ve B.","Matematikçiler ikisini de inceledi: ikisi de uzun vadede kesinlikle kaybettiriyor.","Ama tuhaf bir matematikçi, ikisini sırayla oynayarak zengin olduğunu iddia ediyor..."],
  q:"A oyunu ve B oyunu tek başına oynandığında uzun vadede kesin para kaybettiriyor. Bu iki oyunu rastgele karıştırarak oynarsan ne olur?",g:parrondoX,
  o:["Daha da hızlı kaybedersin","Yine aynı hızda kaybedersin","Uzun vadede KAZANIRSIN","Ne kazanır ne kaybedersin"],c:2,a:"Kazanırsın!",
  s:["<b>Oyun A:</b> Hafif hileli bir para; kazanma olasılığı %49,5. Yavaş ama kesin kaybettirir.","<b>Oyun B:</b> İki para kullanır. Sermayen 3'ün katıysa 'kötü para' (%9,5 kazanma), değilse 'iyi para' (%74,5 kazanma) atılır.","B tek başına neden kaybettirir? Sermaye dinamikleri seni sık sık '3'ün katı' durumuna sürükler ve kötü para avantajı yer.","A'yı araya karıştırınca sermayenin 3'e bölümünden kalanı 'rastgeleleşir'. Kötü paraya düşme sıklığı yaklaşık 1/3'e iner; iyi paranın büyük avantajı baskın çıkar.","Sonuç: iki kaybettiren oyun birlikte kazandırır!"],
  w:"Sır, B'nin sermayeye <b>bağımlı</b> olmasıdır. A, 'sallayarak' sistemi B'nin iyi bölgelerine iter; tıpkı titreşen bir kum tepsisinde tanelerin belli bir yöne akması gibi. Bu fikir 'Brownian ratchet' (Feynman cırcırı) adlı fizik düzeneğinden doğdu. Biyolojide hücre içindeki moleküler motorların rastgele hareketlerden nasıl düzenli bir iş çıkardığını açıklamakta kullanılır.",
  h:"İspanyol fizikçi <b>Juan M. R. Parrondo</b> paradoksu 1996'da, Richard Feynman'ın 1960'larda derslerinde anlattığı 'Brown cırcırı' düşünce deneyini incelerken buldu. Avustralyalı <b>Gregory Harmer</b> ve <b>Derek Abbott</b> bunu 1999'da <i>Nature</i> dergisinde 'Kaybettiren stratejiler kazanabilir' başlığıyla yayımladı ve büyük ilgi gördü.",
  n:"Ne yazık ki gerçek kumarhanelerde işe yaramaz: oradaki oyunlar sermayene bağlı değildir. Kasa yine kazanır! 🎰"}
];
